'use client';

import type { ReactNode } from 'react';
import { cn } from '../../utils';

export interface EmptyStateProps {
  /** An illustration from `illustrations.tsx`, or any drawn SVG. */
  art?: ReactNode;
  title: string;
  /** One line on why it is empty and what fills it. */
  description?: string;
  /** A single action. Omit when the user cannot do anything about it. */
  action?: ReactNode;
  size?: 'sm' | 'default';
  className?: string;
}

/**
 * The state a trading UI spends most of its life in.
 *
 * Before the open, between sessions, on a fresh account, every list here is
 * empty - so an empty state is not a corner case to apologise for, it is a
 * primary screen. Each one names what is missing and what would fill it,
 * rather than saying "no data".
 */
export function EmptyState({
  art,
  title,
  description,
  action,
  size = 'default',
  className,
}: EmptyStateProps) {
  return (
    <div
      className={cn(
        'flex flex-col items-center justify-center gap-3 text-center',
        size === 'sm' ? 'px-4 py-6' : 'px-6 py-10',
        className,
      )}
    >
      {art && <div className={cn('opacity-90', size === 'sm' && 'scale-75')}>{art}</div>}
      <div className="flex max-w-[34ch] flex-col gap-1">
        <p className="text-foreground text-xs font-semibold tracking-wide">{title}</p>
        {description && (
          <p className="text-muted-foreground text-[11px] leading-relaxed">{description}</p>
        )}
      </div>
      {action}
    </div>
  );
}

'use client';

import type { SVGProps } from 'react';
import { cn } from '../../utils';

/**
 * Empty-state illustrations.
 *
 * One drawn family, not five unrelated pictures: every one is built from the
 * same vocabulary - hairline rules at the same rhythm, a dashed reference
 * line, and small tick marks - so an empty book and an empty blotter read as
 * two states of the same instrument.
 *
 * All strokes are `currentColor` at graded opacity, so the caller sets one
 * colour and the drawing stays in the theme. 1.25px stroke throughout, matching
 * the hairline weight of the components they sit inside.
 */

type IllustrationProps = SVGProps<SVGSVGElement>;

function Frame({ className, children, ...props }: IllustrationProps) {
  return (
    <svg
      viewBox="0 0 120 80"
      fill="none"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={cn('h-20 w-auto text-muted-foreground', className)}
      {...props}
    >
      {children}
    </svg>
  );
}

/** Empty ladder: rows thinning out, with a gap where the touch would be. */
export function EmptyBookArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      {[0, 1, 2].map((i) => (
        <g key={`a${i}`} opacity={0.18 + i * 0.07}>
          <rect
            x={18}
            y={8 + i * 10}
            width={84 - i * 6}
            height={5}
            rx={1.5}
            fill="currentColor"
          />
        </g>
      ))}
      {/* The spread. The one place the drawing breaks rhythm, because that is
          the thing the component is for. */}
      <line
        x1={10}
        y1={43}
        x2={110}
        y2={43}
        stroke="currentColor"
        strokeWidth={1.25}
        strokeDasharray="3 4"
        opacity={0.55}
      />
      {[0, 1, 2].map((i) => (
        <g key={`b${i}`} opacity={0.25 - i * 0.07}>
          <rect
            x={18}
            y={52 + i * 10}
            width={72 + i * 6}
            height={5}
            rx={1.5}
            fill="currentColor"
          />
        </g>
      ))}
    </Frame>
  );
}

/** Empty tape: a paper strip running out, prints trailing to nothing. */
export function EmptyTapeArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      <rect
        x={14}
        y={16}
        width={92}
        height={48}
        rx={3}
        stroke="currentColor"
        strokeWidth={1.25}
        opacity={0.35}
      />
      {[0, 1, 2, 3].map((i) => (
        <g key={i} opacity={0.4 - i * 0.09}>
          <rect x={24} y={26 + i * 10} width={18} height={4} rx={1.5} fill="currentColor" />
          <rect x={50} y={26 + i * 10} width={22} height={4} rx={1.5} fill="currentColor" />
          <rect x={80} y={26 + i * 10} width={14} height={4} rx={1.5} fill="currentColor" />
        </g>
      ))}
      {/* Sprocket perforations, so it reads as tape rather than a table. */}
      {[0, 1, 2, 3, 4].map((i) => (
        <circle key={i} cx={9} cy={22 + i * 9} r={1.4} fill="currentColor" opacity={0.3} />
      ))}
      {[0, 1, 2, 3, 4].map((i) => (
        <circle key={i} cx={111} cy={22 + i * 9} r={1.4} fill="currentColor" opacity={0.3} />
      ))}
    </Frame>
  );
}

/** No positions: a flat book — axis with nothing plotted against it. */
export function EmptyPositionsArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      <line x1={18} y1={14} x2={18} y2={62} stroke="currentColor" strokeWidth={1.25} opacity={0.4} />
      <line x1={18} y1={62} x2={104} y2={62} stroke="currentColor" strokeWidth={1.25} opacity={0.4} />
      {[0, 1, 2].map((i) => (
        <line
          key={i}
          x1={15}
          y1={22 + i * 14}
          x2={18}
          y2={22 + i * 14}
          stroke="currentColor"
          strokeWidth={1.25}
          opacity={0.3}
        />
      ))}
      <line
        x1={18}
        y1={40}
        x2={104}
        y2={40}
        stroke="currentColor"
        strokeWidth={1.25}
        strokeDasharray="3 4"
        opacity={0.5}
      />
      <circle cx={61} cy={40} r={3} stroke="currentColor" strokeWidth={1.25} opacity={0.55} />
    </Frame>
  );
}

/** No orders: a blank ticket, fields unfilled. */
export function EmptyOrdersArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      <path
        d="M30 10h52a3 3 0 0 1 3 3v54a3 3 0 0 1-3 3H30a3 3 0 0 1-3-3V13a3 3 0 0 1 3-3Z"
        stroke="currentColor"
        strokeWidth={1.25}
        opacity={0.35}
      />
      <rect x={36} y={19} width={28} height={4} rx={1.5} fill="currentColor" opacity={0.4} />
      {[0, 1, 2].map((i) => (
        <rect
          key={i}
          x={36}
          y={32 + i * 11}
          width={40 - i * 8}
          height={4}
          rx={1.5}
          fill="currentColor"
          opacity={0.22}
        />
      ))}
      <line
        x1={36}
        y1={60}
        x2={76}
        y2={60}
        stroke="currentColor"
        strokeWidth={1.25}
        strokeDasharray="3 4"
        opacity={0.45}
      />
    </Frame>
  );
}

/** Empty watchlist: rows waiting, each with a flat line where a trend goes. */
export function EmptyWatchlistArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      {[0, 1, 2].map((i) => (
        <g key={i} opacity={0.4 - i * 0.1}>
          <rect x={14} y={18 + i * 16} width={20} height={4} rx={1.5} fill="currentColor" />
          <line
            x1={44}
            y1={20 + i * 16}
            x2={78}
            y2={20 + i * 16}
            stroke="currentColor"
            strokeWidth={1.25}
            strokeDasharray="3 4"
          />
          <rect x={88} y={18 + i * 16} width={18} height={4} rx={1.5} fill="currentColor" />
        </g>
      ))}
    </Frame>
  );
}

/** Nothing to chart: axes with a dashed, featureless series. */
export function EmptyChartArt(props: IllustrationProps) {
  return (
    <Frame {...props}>
      <line x1={16} y1={12} x2={16} y2={62} stroke="currentColor" strokeWidth={1.25} opacity={0.4} />
      <line x1={16} y1={62} x2={106} y2={62} stroke="currentColor" strokeWidth={1.25} opacity={0.4} />
      <path
        d="M16 48 L38 38 L58 44 L78 28 L106 34"
        stroke="currentColor"
        strokeWidth={1.25}
        strokeDasharray="3 4"
        opacity={0.45}
      />
      {[0, 1, 2, 3].map((i) => (
        <line
          key={i}
          x1={30 + i * 22}
          y1={62}
          x2={30 + i * 22}
          y2={65}
          stroke="currentColor"
          strokeWidth={1.25}
          opacity={0.3}
        />
      ))}
    </Frame>
  );
}

'use client';

import type { ComponentProps } from 'react';
import { cn } from '../../utils';

/**
 * Loading states.
 *
 * Each skeleton is shaped like the thing it replaces - the ladder skeleton has
 * a spread row, the chart skeleton has an axis and a volume pane - so the
 * layout does not jump when real data lands and the eye already knows where to
 * look. A generic grey box would be cheaper and would cost a reflow every time.
 *
 * The pulse is opacity only, and stops under `prefers-reduced-motion`.
 */
export function Skeleton({ className, ...props }: ComponentProps<'div'>) {
  return (
    <div
      data-slot="skeleton"
      className={cn('bg-muted-foreground/15 animate-shimmer rounded-sm', className)}
      {...props}
    />
  );
}

/** Deterministic widths: random ones would re-roll on every render. */
const LADDER_WIDTHS = [62, 48, 74, 55, 68, 44, 80, 51, 66, 58, 72, 46];

export function OrderBookSkeleton({ depth = 8, className }: { depth?: number; className?: string }) {
  const row = (key: string, i: number, side: 'bid' | 'ask') => (
    <div key={key} className="flex items-center gap-2 px-2.5 py-[5px]">
      <Skeleton
        className={cn('h-2.5 flex-1', side === 'bid' ? 'bg-up/15' : 'bg-down/15')}
        style={{ maxWidth: `${LADDER_WIDTHS[i % LADDER_WIDTHS.length]}%` }}
      />
      <Skeleton className="h-2.5 w-10" />
      <Skeleton className="h-2.5 w-8" />
    </div>
  );

  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-2 border-b px-2.5 py-1.5">
        <Skeleton className="h-2 w-10" />
        <Skeleton className="ml-auto h-2 w-8" />
        <Skeleton className="h-2 w-8" />
      </div>
      {Array.from({ length: depth }, (_, i) => row(`a${i}`, i, 'ask'))}
      <div className="bg-muted my-0.5 flex items-center justify-between border-y px-2.5 py-2">
        <Skeleton className="h-2.5 w-16" />
        <Skeleton className="h-2.5 w-20" />
      </div>
      {Array.from({ length: depth }, (_, i) => row(`b${i}`, i + 3, 'bid'))}
    </div>
  );
}

export function TradeTapeSkeleton({ rows = 10, className }: { rows?: number; className?: string }) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-2 border-b px-2.5 py-1.5">
        <Skeleton className="h-2 w-8" />
        <Skeleton className="ml-auto h-2 w-10" />
        <Skeleton className="h-2 w-8" />
      </div>
      {Array.from({ length: rows }, (_, i) => (
        <div key={i} className="grid grid-cols-3 gap-2 px-2.5 py-[5px]">
          <Skeleton className="h-2.5 w-12" />
          <Skeleton className="h-2.5 w-12 justify-self-end" />
          <Skeleton className="h-2.5 w-8 justify-self-end" />
        </div>
      ))}
    </div>
  );
}

/** Candle bars at varied heights around a baseline, plus axis and volume. */
const CANDLE_HEIGHTS = [38, 52, 44, 61, 49, 70, 57, 42, 66, 51, 74, 46, 59, 68, 40, 55, 63, 47];

export function CandleChartSkeleton({
  height = 320,
  className,
}: {
  height?: number;
  className?: string;
}) {
  return (
    <div
      className={cn('flex w-full flex-col gap-2 p-2', className)}
      style={{ height }}
      aria-hidden="true"
    >
      <div className="flex min-h-0 flex-1 items-end gap-[3px] pr-14">
        {CANDLE_HEIGHTS.concat(CANDLE_HEIGHTS).map((h, i) => (
          <Skeleton
            key={i}
            className="min-w-[3px] flex-1"
            style={{ height: `${h}%`, animationDelay: `${(i % 12) * 60}ms` }}
          />
        ))}
      </div>
      <div className="flex h-[16%] items-end gap-[3px] pr-14">
        {CANDLE_HEIGHTS.concat(CANDLE_HEIGHTS).map((h, i) => (
          <Skeleton
            key={i}
            className="min-w-[3px] flex-1 opacity-60"
            style={{ height: `${h * 0.7}%`, animationDelay: `${(i % 12) * 60}ms` }}
          />
        ))}
      </div>
      <div className="flex justify-between pr-14">
        {Array.from({ length: 6 }, (_, i) => (
          <Skeleton key={i} className="h-2 w-8" />
        ))}
      </div>
    </div>
  );
}

export function TableSkeleton({
  rows = 4,
  columns = 6,
  className,
}: {
  rows?: number;
  columns?: number;
  className?: string;
}) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-4 border-b px-2.5 py-2">
        {Array.from({ length: columns }, (_, i) => (
          <Skeleton key={i} className={cn('h-2', i === 0 ? 'w-14' : 'flex-1')} />
        ))}
      </div>
      {Array.from({ length: rows }, (_, r) => (
        <div key={r} className="flex gap-4 border-b px-2.5 py-2.5">
          {Array.from({ length: columns }, (_, i) => (
            <Skeleton key={i} className={cn('h-2.5', i === 0 ? 'w-14' : 'flex-1')} />
          ))}
        </div>
      ))}
    </div>
  );
}

export function WatchlistSkeleton({ rows = 6, className }: { rows?: number; className?: string }) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      {Array.from({ length: rows }, (_, i) => (
        <div key={i} className="flex items-center gap-2.5 border-b px-2.5 py-2">
          <Skeleton className="h-2.5 w-12" />
          <Skeleton className="h-4 w-14" />
          <Skeleton className="ml-auto h-2.5 w-12" />
          <Skeleton className="h-2.5 w-10" />
        </div>
      ))}
    </div>
  );
}

'use client';

import { BellIcon, BellRingIcon, XIcon } from 'lucide-react';
import { useState } from 'react';
import { formatPercent, formatPrice, roundToTick } from '../../format';
import { useInstrument } from '../../theme/theme-provider';
import type { Instrument } from '../../types';
import { cn } from '../../utils';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import { EmptyState } from './empty-state';
import { EmptyWatchlistArt } from './illustrations';
import { NumberField } from './number-field';
import { SegmentedControl } from './segmented-control';

export type AlertDirection = 'above' | 'below';

export interface PriceAlert {
  id: string;
  symbol: string;
  price: number;
  direction: AlertDirection;
  /** Set once the condition has fired. */
  triggeredAt?: number;
}

export interface PriceAlertsProps {
  alerts: PriceAlert[];
  /** Current price per symbol, for the distance readout. */
  prices: Record<string, number>;
  instrument?: Partial<Instrument>;
  /** Symbol the inline composer creates alerts for. */
  symbol?: string;
  onCreate?: (alert: Omit<PriceAlert, 'id'>) => void;
  onRemove?: (alert: PriceAlert) => void;
  className?: string;
}

/**
 * Price alerts, with how far away each one is.
 *
 * The distance is the useful column, not the target: "4.80 above" tells you
 * whether this fires today or next month, which a bare target price never does.
 * Triggered alerts stay in the list rather than vanishing — an alert that fired
 * and disappeared is indistinguishable from one you never set.
 */
export function PriceAlerts({
  alerts,
  prices,
  instrument,
  symbol,
  onCreate,
  onRemove,
  className,
}: PriceAlertsProps) {
  const inst = useInstrument(instrument);
  const [draftPrice, setDraftPrice] = useState<number | null>(null);
  const [direction, setDirection] = useState<AlertDirection>('above');

  const current = symbol ? prices[symbol] : undefined;

  const submit = () => {
    if (!symbol || !draftPrice || !onCreate) return;
    onCreate({ symbol, price: roundToTick(draftPrice, inst.tickSize), direction });
    setDraftPrice(null);
  };

  return (
    <div className={cn('flex flex-col', className)}>
      {symbol && onCreate && (
        <div className="flex items-end gap-2 border-b p-2.5">
          <SegmentedControl
            size="sm"
            aria-label="Alert direction"
            value={direction}
            onChange={setDirection}
            options={[
              { value: 'above', label: 'Above' },
              { value: 'below', label: 'Below' },
            ]}
          />
          <NumberField
            label={`${symbol} price`}
            value={draftPrice}
            onChange={setDraftPrice}
            step={inst.tickSize}
            min={0}
            placeholder={current ? formatPrice(current, inst.pricePrecision) : '0.00'}
            className="flex-1"
          />
          <Button size="sm" disabled={!draftPrice} onClick={submit}>
            <BellIcon />
            Add
          </Button>
        </div>
      )}

      {alerts.length === 0 ? (
        <EmptyState
          size="sm"
          art={<EmptyWatchlistArt />}
          title="No alerts set"
          description="Set a level and this tells you when price reaches it."
        />
      ) : (
        <ul className="flex flex-col">
          {alerts.map((alert) => {
            const price = prices[alert.symbol];
            const distance = price !== undefined ? alert.price - price : undefined;
            const triggered = alert.triggeredAt !== undefined;
            // An alert is "reached" when price is already past the level, which
            // can be true before the feed has formally triggered it.
            const reached =
              distance !== undefined &&
              (alert.direction === 'above' ? distance <= 0 : distance >= 0);

            return (
              <li
                key={alert.id}
                className={cn(
                  'flex items-center gap-2.5 border-b px-2.5 py-2 text-xs',
                  triggered && 'bg-primary/5',
                )}
              >
                {triggered ? (
                  <BellRingIcon className="text-primary size-3.5 shrink-0" />
                ) : (
                  <BellIcon className="text-muted-foreground size-3.5 shrink-0" />
                )}

                <span className="w-14 shrink-0 font-semibold">{alert.symbol}</span>

                <span className="text-muted-foreground shrink-0">
                  {alert.direction === 'above' ? '≥' : '≤'}
                </span>
                <span className="font-mono tabular-nums">
                  {formatPrice(alert.price, inst.pricePrecision)}
                </span>

                <span className="ml-auto flex items-center gap-2">
                  {triggered ? (
                    <Badge variant="default">Triggered</Badge>
                  ) : reached ? (
                    <Badge variant="secondary">Reached</Badge>
                  ) : (
                    distance !== undefined && (
                      <span
                        className={cn(
                          'font-mono text-[11px] tabular-nums',
                          distance > 0 ? 'text-up' : 'text-down',
                        )}
                        title="Distance from the current price"
                      >
                        {distance > 0 ? '+' : ''}
                        {formatPrice(distance, inst.pricePrecision)}
                        {price ? ` · ${formatPercent(distance / price, 1)}` : ''}
                      </span>
                    )
                  )}
                  {onRemove && (
                    <Button
                      size="xs"
                      variant="ghost"
                      aria-label={`Remove alert for ${alert.symbol}`}
                      onClick={() => onRemove(alert)}
                    >
                      <XIcon />
                    </Button>
                  )}
                </span>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

'use client';

import { ChevronDownIcon, ChevronUpIcon } from 'lucide-react';
import { useEffect, useId, useState } from 'react';
import { decimalsOf } from '../../format';
import { cn } from '../../utils';
import { Label } from '../ui/label';

export interface NumberFieldProps {
  value: number | null;
  onChange: (value: number | null) => void;
  label?: string;
  /** Unit rendered inside the field, e.g. `USD` or `shares`. */
  suffix?: string;
  step?: number;
  min?: number;
  max?: number;
  /** Decimals to snap to. Defaults to the decimals implied by `step`. */
  precision?: number;
  placeholder?: string;
  disabled?: boolean;
  readOnly?: boolean;
  hideStepper?: boolean;
  /** Marks the field invalid for assistive tech and tints the border. */
  invalid?: boolean;
  className?: string;
}

/**
 * Numeric entry for prices and quantities.
 *
 * Two things most number inputs get wrong, fixed here:
 *
 * 1. The raw string is kept while focused, so typing `1.` or `0.0` is not
 *    rewritten out from under the cursor mid-keystroke. Only a clamped,
 *    rounded number is ever committed.
 * 2. It is `type="text"` with `inputMode="decimal"`, not `type="number"`. A
 *    real number input silently changes value on mouse wheel - one stray
 *    scroll over a price field is a wrong order - and parses by locale.
 *
 * Arrow keys step by `step`; shift-arrow by ten.
 */
export function NumberField({
  value,
  onChange,
  label,
  suffix,
  step = 1,
  min,
  max,
  precision,
  placeholder,
  disabled = false,
  readOnly = false,
  hideStepper = false,
  invalid = false,
  className,
}: NumberFieldProps) {
  const id = useId();
  const decimals = precision ?? decimalsOf(step);
  const [draft, setDraft] = useState(() => (value === null ? '' : String(value)));
  const [editing, setEditing] = useState(false);

  // While the user is typing, the draft is the source of truth.
  useEffect(() => {
    if (!editing) setDraft(value === null ? '' : value.toFixed(decimals));
  }, [value, decimals, editing]);

  const clamp = (n: number) => {
    let out = n;
    if (min !== undefined) out = Math.max(min, out);
    if (max !== undefined) out = Math.min(max, out);
    return Number(out.toFixed(decimals));
  };

  const commit = (text: string) => {
    const trimmed = text.trim();
    if (trimmed === '' || trimmed === '-' || trimmed === '.') {
      onChange(null);
      setDraft('');
      return;
    }
    const parsed = Number(trimmed);
    if (!Number.isFinite(parsed)) {
      setDraft(value === null ? '' : value.toFixed(decimals));
      return;
    }
    const next = clamp(parsed);
    onChange(next);
    setDraft(next.toFixed(decimals));
  };

  const bump = (multiplier: number) => {
    const base = value ?? min ?? 0;
    const next = clamp(base + step * multiplier);
    onChange(next);
    setDraft(next.toFixed(decimals));
  };

  return (
    <div className={cn('group flex min-w-0 flex-col gap-1', className)}>
      {label && <Label htmlFor={id}>{label}</Label>}
      <div
        data-slot="number-field"
        className={cn(
          'border-input bg-background flex h-9 items-stretch overflow-hidden rounded-md border shadow-xs transition-[color,box-shadow]',
          'focus-within:border-ring focus-within:ring-ring/50 focus-within:ring-[3px]',
          invalid && 'border-destructive focus-within:ring-destructive/20',
          disabled && 'pointer-events-none opacity-50',
        )}
      >
        <input
          id={id}
          type="text"
          inputMode="decimal"
          autoComplete="off"
          spellCheck={false}
          aria-invalid={invalid || undefined}
          className="text-foreground placeholder:text-muted-foreground/70 min-w-0 flex-1 bg-transparent px-2 text-right font-mono text-sm tabular-nums outline-none"
          value={draft}
          placeholder={placeholder}
          disabled={disabled}
          readOnly={readOnly}
          onFocus={() => setEditing(true)}
          onChange={(e) => {
            const next = e.target.value;
            if (/^-?\d*\.?\d*$/.test(next)) setDraft(next);
          }}
          onBlur={() => {
            setEditing(false);
            commit(draft);
          }}
          onKeyDown={(e) => {
            if (readOnly || disabled) return;
            if (e.key === 'ArrowUp') {
              e.preventDefault();
              bump(e.shiftKey ? 10 : 1);
            } else if (e.key === 'ArrowDown') {
              e.preventDefault();
              bump(e.shiftKey ? -10 : -1);
            } else if (e.key === 'Enter') {
              commit(draft);
            }
          }}
        />
        {suffix && (
          <span className="text-muted-foreground bg-muted flex items-center border-l px-2 text-[10px]">
            {suffix}
          </span>
        )}
        {!hideStepper && !readOnly && (
          <div className="flex flex-col border-l">
            <button
              type="button"
              aria-label="Increase"
              // Not a tab stop: arrow keys already do this from the input, and
              // two extra stops per field makes a ticket slow to tab through.
              tabIndex={-1}
              disabled={disabled}
              className="text-muted-foreground hover:bg-accent hover:text-foreground flex flex-1 cursor-pointer items-center justify-center border-b px-1"
              onClick={() => bump(1)}
            >
              <ChevronUpIcon className="size-3" />
            </button>
            <button
              type="button"
              aria-label="Decrease"
              tabIndex={-1}
              disabled={disabled}
              className="text-muted-foreground hover:bg-accent hover:text-foreground flex flex-1 cursor-pointer items-center justify-center px-1"
              onClick={() => bump(-1)}
            >
              <ChevronDownIcon className="size-3" />
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

